 {id:'huggingface',name:'Hugging Face — Deep RL Course',provider:'Hugging Face / free open course',symbol:'H',tone:'gold',units:8,estimate:'~27–36 hours incl. exercises',minutes:1890,link:'https://huggingface.co/learn/deep-rl-course/en/unit0/introduction',detail:'Practical demonstrations and exercises; useful for connecting research concepts to code.',why:'Do not postpone reading papers until you finish these practical units.',topics:['Intro and foundations','Q-learning fundamentals','Deep Q-learning','Policy gradients','Practical policy optimization','Actor–critic & implementation','Additional deep RL concepts','Capstone, evaluation & practice']},
 {id:'stanford',name:'Stanford CS 234 — Reinforcement Learning',provider:'Stanford / Emma Brunskill · optional alternative',symbol:'ST',tone:'blue',units:16,estimate:'~20 hours of lectures',minutes:1200,link:'https://www.youtube.com/playlist?list=PLoROMvodv4rN4wG6Nk6sNpTEbuOSosZdX',detail:'An excellent alternative foundation course, rather than another required playlist.',why:'Choose it if its presentation makes concepts clearer. You do not need to complete both it and Silver.',topics:Array.from({length:16},(_,i)=>`Video ${i+1}`)}
