 {id:2,title:'Map the research landscape',subtitle:'Explore',description:'Understand the major RL directions without prematurely committing to one.',exit:'Explain major research areas and compare roughly 8–12 seed surveys.',tasks:['Survey robust, safe and fault-tolerant RL','Survey continual, transfer, meta-RL and generalization','Survey offline, model-based and multi-agent RL','Compare 8–12 reputable surveys in a literature matrix']},
 {id:3,title:'Compare & shortlist topics',subtitle:'Synthesize',description:'Identify 2–3 compelling review directions and why they matter.',exit:'Explain the strengths, gaps and tradeoffs of two or three topics.',tasks:['Write 2–3 candidate topic descriptions','Compare importance, interest, literature depth and feasibility','Find the most relevant recent existing surveys','Record unresolved uncertainties for each candidate']},
 {id:4,title:'Validate the survey scope',subtitle:'Decide',description:'Test that the survey can provide a novel, evidence-supported contribution.',exit:'Have PI-discussed questions, a justified review need and a preliminary search protocol.',tasks:['Draft 2–3 research questions and scope boundaries','Compare closely related published surveys','Pilot search keywords and screening criteria','Discuss topic, novelty and feasibility with PI']},
 {id:5,title:'Search & synthesize evidence',subtitle:'Investigate',description:'Follow a documented literature search, critically compare studies and build a taxonomy.',exit:'Have a transparent search log, credible evidence matrix and defensible synthesis.',tasks:['Document searches, inclusion/exclusion rules and screening','Critically examine core primary papers','Build cross-paper comparisons and a working taxonomy','Identify supported disagreements, limitations and open questions']},
 {id:6,title:'Write the survey',subtitle:'Author',description:'Turn evidence into a logical review that helps readers understand the field.',exit:'A complete manuscript makes an argument supported by accurately cited evidence.',tasks:['Draft introduction and motivating research questions','Explain search/review methodology and taxonomy','Write comparison and synthesis sections','Draft limitations, research agenda and conclusion']},
 {id:7,title:'Revise & submit',subtitle:'Publish',description:'Strengthen claims, check completeness and select an appropriate venue.',exit:'Quality-checked manuscript with PI sign-off and appropriate submission materials.',tasks:['Check citation accuracy and scope coverage','Test every claim against evidence and limitations','Revise with PI/peer feedback','Select venue, format manuscript and submit when ready']}
