const defaultState=()=>({schema:1,createdAt:Date.now(),currentStage:1,stageTasks:{},completedStages:[],courseProgress:{},papers:[],documents:[],sessions:[],journal:[],nextAction:'Watch David Silver Lecture 1, explain the MDP interaction loop, and start your literature matrix.',blocker:'',dailyGoal:120,weeklyGoal:1200,feedArea:'all',feedCache:{},planNote:'November: 18–22 hrs/week (target 20). December: 30–35 hrs/week (target 33). Research time grows as tutorial time falls.'});
let state=defaultState();
try{const saved=JSON.parse(localStorage.getItem(STATE_KEY)||'null');if(saved&&saved.schema===1){state={...state,...saved};if(!Array.isArray(state.papers))state.papers=[];if(!Array.isArray(state.documents))state.documents=[];if(!Array.isArray(state.sessions))state.sessions=[];if(!Array.isArray(state.journal))state.journal=[];}}catch(e){console.warn('Could not read saved progress',e)}
let ui={page:'home',paperFilter:'all',paperSearch:'',courseModal:null,paperEdit:null,timer:{running:false,started:0,elapsed:0},feedItems:[],feedStatus:'idle',quoteIndex:Math.floor(Math.random()*quotes.length),pendingPaper:null};
const save=()=>{try{localStorage.setItem(STATE_KEY,JSON.stringify(state))}catch(e){toast('Browser storage is full. Export a backup in Settings.')}};
let toastTimer;
function toast(message){const el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3700)}
const main=()=>document.getElementById('main');
const stage=()=>stages.find(s=>s.id===state.currentStage)||stages[0];
const taskDone=(id,i)=>!!(state.stageTasks[id]||[]).includes(i);
const stageProgress=id=>{const s=stages.find(x=>x.id===id);return s?Math.round(100*s.tasks.filter((_,i)=>taskDone(id,i)).length/s.tasks.length):0};
const courseDone=id=>(state.courseProgress[id]||[]).length;
const coursePercent=c=>Math.round(courseDone(c.id)/c.units*100);
const paperCount=status=>state.papers.filter(p=>p.status===status).length;
const totalMinutes=()=>state.sessions.reduce((a,s)=>a+num(s.minutes),0);
const minutesOn=d=>state.sessions.filter(s=>s.date===d).reduce((a,s)=>a+num(s.minutes),0);
const activeOn=d=>minutesOn(d)>=15;
function streak(){let pos=activeOn(day())?0:-1;let total=0;while(pos>-3000&&activeOn(dateOffset(pos))){total++;pos--;}return total}
const percentDaily=()=>Math.round(Math.min(100,minutesOn(day())/state.dailyGoal*100));
const paperStatusText={queue:'To read',reading:'Reading',read:'Read',included:'Included',excluded:'Excluded'};
function badgeClass(status){return status==='included'?'':status==='reading'?'amber':status==='excluded'?'grey':status==='read'?'purple':'grey'}
function nav(page){ui.page=page;location.hash=page;render();window.scrollTo({top:0,behavior:'instant'})}
function pageHeader(title,subtitle,actions=''){return `<section class="page-head"><div><div class="eyebrow">RESEARCH WORKSPACE</div><h1>${title}</h1><p>${subtitle}</p></div>${actions}</section>`}
function empty(icon,title,description,action=''){return `<div class="empty"><div class="empty-icon">${icon}</div><strong>${title}</strong><p>${description}</p>${action}</div>`}
function progressBar(p){return `<div class="progress-track"><div class="progress-fill" style="width:${clamp(num(p),0,100)}%"></div></div>`}
function activePaperSnippet(p){return `<div class="course-row"><span class="course-symbol">◈</span><div class="course-content"><strong>${escaped(p.title)}</strong><small>${escaped(p.area||'General RL')} · ${paperStatusText[p.status]||'Queued'}</small></div><button class="btn btn-ghost btn-small" data-action="edit-paper" data-id="${escaped(p.id)}">Open</button></div>`}
function render(){
 const titles={home:'Overview',courses:'Learning courses',roadmap:'Research roadmap',papers:'Paper library',documents:'Documents & PDFs',feed:'RL research feed',timer:'Focus & streaks',journal:'Research journal',settings:'Backup & settings'};
 document.getElementById('crumb-name').textContent=titles[ui.page]||'Overview';
 document.getElementById('today-chip').textContent=new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric',year:'numeric'});
 document.querySelectorAll('[data-nav]').forEach(x=>x.classList.toggle('active',x.dataset.nav===ui.page));
 const pages={home:renderHome,courses:renderCourses,roadmap:renderRoadmap,papers:renderPapers,documents:renderDocs,feed:renderFeed,timer:renderTimer,journal:renderJournal,settings:renderSettings};
 main().innerHTML=(pages[ui.page]||renderHome)();
 if(ui.page==='timer')paintTimer();
 if((ui.page==='feed'||ui.page==='home')&&ui.feedStatus==='idle')loadFeed();
}
